SET NOCOUNT ON;
USE master;
IF DB_ID(N'DemoERP') IS NOT NULL
BEGIN ALTER DATABASE [DemoERP] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE [DemoERP]; END
GO
CREATE DATABASE [DemoERP];
GO
USE [DemoERP];
GO
CREATE TABLE dbo.Kunden (
  KundenNr int NOT NULL PRIMARY KEY,
  Firma nvarchar(100) NOT NULL,
  Branche nvarchar(50) NOT NULL,
  PLZ nvarchar(10) NOT NULL,
  Ort nvarchar(50) NOT NULL,
  Ansprechpartner nvarchar(80) NOT NULL,
  Email nvarchar(100) NOT NULL,
  KundeSeit date NOT NULL
);
CREATE TABLE dbo.Artikel (
  ArtikelNr nvarchar(20) NOT NULL PRIMARY KEY,
  Bezeichnung nvarchar(100) NOT NULL,
  Warengruppe nvarchar(50) NOT NULL,
  Einheit nvarchar(10) NOT NULL,
  Listenpreis decimal(10,2) NOT NULL,
  Lagerbestand int NOT NULL,
  Mindestbestand int NOT NULL
);
CREATE TABLE dbo.Auftraege (
  AuftragsNr int NOT NULL PRIMARY KEY,
  KundenNr int NOT NULL REFERENCES dbo.Kunden(KundenNr),
  Auftragsdatum date NOT NULL,
  Liefertermin date NOT NULL,
  Status char(1) NOT NULL,
  Bearbeiter nvarchar(50) NOT NULL
);
CREATE TABLE dbo.Auftragspositionen (
  AuftragsNr int NOT NULL REFERENCES dbo.Auftraege(AuftragsNr),
  PosNr int NOT NULL,
  ArtikelNr nvarchar(20) NOT NULL REFERENCES dbo.Artikel(ArtikelNr),
  Menge int NOT NULL,
  Einzelpreis decimal(10,2) NOT NULL,
  RabattProzent decimal(5,2) NOT NULL,
  PRIMARY KEY (AuftragsNr, PosNr)
);
CREATE TABLE dbo.Anlagen (
  AnlagenNr nvarchar(20) NOT NULL PRIMARY KEY,
  KundenNr int NOT NULL REFERENCES dbo.Kunden(KundenNr),
  Bezeichnung nvarchar(100) NOT NULL,
  Typ nvarchar(30) NOT NULL,
  Baujahr int NOT NULL,
  Standort nvarchar(80) NOT NULL
);
CREATE TABLE dbo.Pruefungen (
  PruefNr int NOT NULL PRIMARY KEY,
  AnlagenNr nvarchar(20) NOT NULL REFERENCES dbo.Anlagen(AnlagenNr),
  Pruefart char(1) NOT NULL,
  Pruefdatum date NOT NULL,
  Ergebnis nvarchar(20) NOT NULL,
  NaechstePruefung date NOT NULL,
  Pruefer nvarchar(50) NOT NULL
);
CREATE TABLE dbo.Reklamationen (
  ReklamationsNr int NOT NULL PRIMARY KEY,
  AuftragsNr int NOT NULL REFERENCES dbo.Auftraege(AuftragsNr),
  Eingang date NOT NULL,
  Grund nvarchar(200) NOT NULL,
  Status nvarchar(20) NOT NULL,
  Verantwortlich nvarchar(50) NOT NULL
);
GO
CREATE VIEW dbo.v_OffeneAuftraege AS
SELECT a.AuftragsNr, a.KundenNr, k.Firma, a.Auftragsdatum, a.Liefertermin,
       a.Status, a.Bearbeiter,
       CAST(SUM(p.Menge * p.Einzelpreis * (100 - p.RabattProzent) / 100) AS decimal(12,2)) AS Auftragswert
FROM dbo.Auftraege a
JOIN dbo.Kunden k ON k.KundenNr = a.KundenNr
JOIN dbo.Auftragspositionen p ON p.AuftragsNr = a.AuftragsNr
WHERE a.Status IN ('O', 'F')
GROUP BY a.AuftragsNr, a.KundenNr, k.Firma, a.Auftragsdatum, a.Liefertermin, a.Status, a.Bearbeiter;
GO
DECLARE @heute date = CAST(GETDATE() AS date);
GO
